     $LSNames = $Server.LinkedServers
     &quot;$(Get-Date) $ServerName connection success.&quot; | Out-File $OutputFile -Append

     &lt;# If no linked servers defined. #&gt;  
     if ($LSNames.Count -eq 0) 
